#!/usr/bin/env python3
# Generated By: Claude Code (Claude Opus 4.6)
"""Filter findings anchored to files the PR never touched.

Enforces the same scope rule ``pr-scope.sh`` gives the review agents:
"Report findings ONLY for the changed files listed above." A finding
survives when any of its primary locations names a path in the diff's
changed-path set — added, modified, deleted, renamed (either name), or
copied.

Deliberately file-level, not line-level. ``git diff base...HEAD``
resolves against HEAD, so lines a PR *removed* have no addressable
position. A reviewer reporting "this PR deleted X, so the caller is now
orphaned" must anchor to the nearest surviving line, which a line-level
test misreads as out-of-scope. Precision degrades in proportion to how
deletion-heavy the diff is; a pure-deletion PR filters to zero. Line
overlap is still computed and reported to stderr as an advisory, but it
never removes a finding.

Skips (no-op) when --base-ref is not provided — full-repo reviews keep
all findings.

Usage:
    python diff-scope-filter.py --stage-dir ./.tmp-review/10-merged/ --base-ref origin/devel
"""

import argparse
import re
import subprocess
import sys
from pathlib import Path

SKILL_ROOT = Path(__file__).resolve().parent.parent
PLUGIN_ROOT = SKILL_ROOT.parent.parent

sys.path.insert(0, str(PLUGIN_ROOT))
from scripts.envelope import load_stage_dir, write_stage_dir  # noqa: E402


def get_changed_paths(base_ref: str) -> set[str]:
    """Every path touched by the diff, whatever the change type.

    Renames and copies contribute both the pre-image and post-image path
    so a finding anchored to either name survives. Deleted paths are
    included — the deletion is the change, and findings about it are in
    scope even though the file is absent from HEAD.
    """
    result = subprocess.run(
        ["git", "diff", f"{base_ref}...HEAD", "--name-status"],
        capture_output=True, text=True, check=True,
    )

    paths: set[str] = set()
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split("\t")
        # R<score>/C<score> carry both old and new names; the rest carry one.
        paths.update(f for f in fields[1:] if f)
    return paths


def get_changed_lines(base_ref: str) -> dict[str, set[int]]:
    """Post-image line numbers per file. Advisory only — see module docstring."""
    result = subprocess.run(
        ["git", "diff", f"{base_ref}...HEAD", "-U0"],
        capture_output=True, text=True, check=True,
    )

    changed: dict[str, set[int]] = {}
    current_file = None

    for line in result.stdout.splitlines():
        m = re.match(r"^\+\+\+ b/(.+)$", line)
        if m:
            current_file = m.group(1)
            changed.setdefault(current_file, set())
            continue

        m = re.match(r"^@@ .+ \+(\d+)(?:,(\d+))? @@", line)
        if m and current_file:
            start = int(m.group(1))
            count = int(m.group(2)) if m.group(2) else 1
            if count == 0:
                # Pure deletion — no post-image line to record.
                continue
            for i in range(start, start + count):
                changed[current_file].add(i)

    return changed


def parse_line_range(line_str: str) -> tuple[int, int]:
    """Parse '42' or '42-50' into (start, end) inclusive."""
    if "-" in line_str:
        a, b = line_str.split("-", 1)
        return int(a), int(b)
    n = int(line_str)
    return n, n


def primary_locations(finding: dict) -> list[dict]:
    """Primary locations, falling back to the first location when none is tagged."""
    locations = finding.get("locations", [])
    primary = [loc for loc in locations if loc.get("role", "primary") == "primary"]
    return primary or locations[:1]


def finding_in_changed_files(finding: dict, changed_paths: set[str]) -> bool:
    """True when any primary location names a path the PR touched."""
    return any(loc["path"] in changed_paths for loc in primary_locations(finding))


def finding_overlaps_lines(finding: dict, changed_lines: dict[str, set[int]]) -> bool:
    """True when any primary location overlaps a changed post-image line."""
    for loc in primary_locations(finding):
        if loc["path"] not in changed_lines:
            continue
        start, end = parse_line_range(loc["line"])
        if set(range(start, end + 1)) & changed_lines[loc["path"]]:
            return True
    return False


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--stage-dir",
        type=Path,
        required=True,
        help="stage directory with _envelope.json + per-finding files (modified in place)",
    )
    parser.add_argument(
        "--base-ref",
        default="",
        help="git ref to diff against (e.g. origin/devel). Empty = skip filtering.",
    )
    args = parser.parse_args(argv)

    if not args.base_ref:
        print("OK: no --base-ref provided, skipping diff-scope filter (full-repo review)")
        return 0

    if not args.stage_dir.is_dir():
        print(f"error: --stage-dir is not a directory: {args.stage_dir}", file=sys.stderr)
        return 2

    try:
        changed_paths = get_changed_paths(args.base_ref)
        changed_lines = get_changed_lines(args.base_ref)
    except subprocess.CalledProcessError as exc:
        print(f"error: git diff failed: {exc.stderr}", file=sys.stderr)
        return 1

    if not changed_paths:
        print(
            "warning: no changed files detected in diff; keeping all findings",
            file=sys.stderr,
        )
        return 0

    envelope, findings = load_stage_dir(args.stage_dir)

    kept: list[dict] = []
    filtered: list[dict] = []

    for finding in findings:
        if finding_in_changed_files(finding, changed_paths):
            kept.append(finding)
        else:
            filtered.append(finding)

    # Advisory: kept findings sitting on untouched lines inside a changed
    # file. Often legitimate (deleted code, orphaned callers), so this is
    # reported and never acted on.
    off_line = [f for f in kept if not finding_overlaps_lines(f, changed_lines)]
    if off_line:
        print(
            f"note: {len(off_line)} of {len(kept)} kept finding(s) anchor to "
            f"unchanged lines within changed files. Expected for deletions and "
            f"orphaned-caller findings; worth a look if the count is high:",
            file=sys.stderr,
        )
        for f in off_line:
            locs = ", ".join(f"{l['path']}:{l['line']}" for l in primary_locations(f))
            print(f"  {f['content_hash']} {f['title']} -> {locs}", file=sys.stderr)

    if not filtered:
        print(f"OK: all {len(findings)} finding(s) anchor to changed files")
        return 0

    issues = envelope.get("issues", [])
    for f in filtered:
        loc_str = ", ".join(f"{l['path']}:{l['line']}" for l in primary_locations(f))
        issues.append({
            # ponytail: findings.schema.json's issue enums have no diff-scope
            # kind and no "info" severity — use the "other" escape hatch and
            # carry the classification in the message prefix. Widen the shared
            # enum only if another skill needs the same category.
            "severity": "warning",
            "kind": "other",
            "message": (
                f"diff_scope_filtered: finding '{f['title']}' ({f['content_hash']}) "
                f"removed — primary location(s) {loc_str} not among the files "
                f"changed by this PR"
            ),
            "source_component": "diff-scope-filter",
        })
    envelope["issues"] = issues

    write_stage_dir(args.stage_dir, envelope, kept)

    print(
        f"OK: {len(filtered)} finding(s) filtered (file not in diff), "
        f"{len(kept)} finding(s) kept"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
